rewrite:
def target_iter(target, scope):
    try:
        return iter(target)
    except TypeError:
        raise BadSpec(f"Group() expected an iterable target, not: {type(target)!r}")

def glomit(self, target, scope):
    scope[MODE] = GROUP
    scope[CUR_AGG] = None
    scope[ACC_TREE] = {}

    if type(self.spec) in (dict, list):
        ret = type(self.spec)()
    else:
        ret = None

    for t in target_iter(target, scope):
        last, ret = ret, scope[glom](t, self.spec, scope)
        if ret is STOP:
            return last
    return ret
